import java.io.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream is = System.in;

    static int readByte() throws IOException {
        if (ptr == len) { len = is.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static String next() throws IOException {
        int c = readByte();
        while (c != -1 && c <= ' ') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') { sb.append((char) c); c = readByte(); }
        return sb.toString();
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c != '-' && (c < '0' || c > '9')) c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = readByte(); }
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        int n = (int) nextLong(), m = (int) nextLong();
        int[] g = new int[n * m];
        for (int i = 0; i < n * m; i++) g[i] = (int) nextLong();
        boolean[] seen = new boolean[n * m];
        int[] q = new int[n * m];
        int best = 0;
        int[] dr = {1, -1, 0, 0}, dc = {0, 0, 1, -1};
        for (int s = 0; s < n * m; s++) {
            if (g[s] == 0 || seen[s]) continue;
            // BFS over one 4-connected house
            int head = 0, tail = 0;
            q[tail++] = s;
            seen[s] = true;
            while (head < tail) {
                int cur = q[head++], x = cur / m, y = cur % m;
                for (int k = 0; k < 4; k++) {
                    int u = x + dr[k], v = y + dc[k];
                    if (u >= 0 && u < n && v >= 0 && v < m && g[u * m + v] != 0 && !seen[u * m + v]) {
                        seen[u * m + v] = true;
                        q[tail++] = u * m + v;
                    }
                }
            }
            best = Math.max(best, tail);
        }
        System.out.println(best);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	nextInt := func() int {
		sc.Scan()
		v, _ := strconv.Atoi(sc.Text())
		return v
	}
	n, m := nextInt(), nextInt()
	g := make([]int, n*m)
	for i := range g {
		g[i] = nextInt()
	}
	seen := make([]bool, n*m)
	q := make([]int, n*m)
	best := 0
	dr := [4]int{1, -1, 0, 0}
	dc := [4]int{0, 0, 1, -1}
	for s := 0; s < n*m; s++ {
		if g[s] == 0 || seen[s] {
			continue
		}
		// BFS over one 4-connected house
		head, tail := 0, 0
		q[tail] = s
		tail++
		seen[s] = true
		for head < tail {
			cur := q[head]
			head++
			x, y := cur/m, cur%m
			for k := 0; k < 4; k++ {
				u, v := x+dr[k], y+dc[k]
				if u >= 0 && u < n && v >= 0 && v < m && g[u*m+v] != 0 && !seen[u*m+v] {
					seen[u*m+v] = true
					q[tail] = u*m + v
					tail++
				}
			}
		}
		best = max(best, tail)
	}
	fmt.Println(best)
}
